from taf.ul.kpi_selector.operations.reset_cu.classical_reset_cu.reset_cu_22R3 import ResetCu22R3


class ResetCu23R1(ResetCu22R3):
    def get_kpi(self):
        """
        Gets kpi for reset cu operation.
        :return: dictionary with timeout, requirement and operation description for reset cu
        :rtype: dict
        """
        if all(
                [
                    "ASIL" in self.bts.smod_hw_types,
                    "ABIP" in self.bts.bbmod_hw_types,
                    self.bts.number_of_bbmods == 1,
                    "AZQP" in self.bts.rmod_hw_types,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies == "TDD",
                    self.bts.radio_protocol == "eCPRI",
                    self.bts.number_of_nr_cells <= 2,
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 180 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.16055"

        elif all(
                [
                    "ASIM" in self.bts.smod_hw_types,
                    "ABIP" in self.bts.bbmod_hw_types,
                    self.bts.number_of_bbmods == 1,
                    "AQQL" in self.bts.rmod_hw_types or "AEQE" in self.bts.rmod_hw_types,
                    self.bts.number_of_rmods <= 2,
                    self.bts.cell_technologies == "TDD",
                    self.bts.radio_protocol == "eCPRI",
                    self.bts.number_of_nr_cells <= 2,
                    self.bts.setup_mode == "NSA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 180 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.16064"

        elif all(
                [
                    "ASIM" in self.bts.smod_hw_types,
                    "ABIP" in self.bts.bbmod_hw_types,
                    self.bts.number_of_bbmods == 1,
                    "AHEGB" in self.bts.rmod_hw_types,
                    "AHLOA" in self.bts.rmod_hw_types or "AHEH" in self.bts.rmod_hw_types,
                    self.bts.number_of_rmods <= 4,
                    self.bts.cell_technologies == "FDD",
                    self.bts.radio_protocol == "CPRI",
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.setup_mode == "SA",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 180 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.16073"

        elif all(
                [
                    "ASIL" in self.bts.smod_hw_types,
                    "ABIP" in self.bts.bbmod_hw_types,
                    self.bts.number_of_bbmods == 1,
                    self.bts.cell_technologies == "FDD",
                    self.bts.radio_protocol == "CPRI",
                    self.bts.number_of_nr_cells <= 3,
                    self.bts.number_of_lte_cells <= 3,
                    self.bts.is_multi_rat,
                    self.bts.setup_mode == "NSA",
                ]
        ):
            self.operation_details["Timeout"] = 150 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19699"

        elif all(
                [
                    "ASIL" in self.bts.smod_hw_types,
                    "ABIP" in self.bts.bbmod_hw_types,
                    self.bts.setup_mode == "NSA",
                    self.bts.number_of_nr_cells <= 4,
                    self.bts.cell_technologies == "MIX",
                    not self.bts.is_multi_rat,
                ]
        ):
            self.operation_details["Timeout"] = 150 + self.restrictions.\
                use_restrictions_from_OM_GEN_SFS_PERF_CAP_10517()
            self.operation_details["Requirement"] = "OM_GEN_SFS_PERF_CAP.19713"

        else:
            return super(ResetCu22R3, self).get_kpi()

        return self.operation_details
